select l.id, 0, 'Sizes and safe multiplication', 'সাইজ ও নিরাপদ গুণ', 'c', '#include <stdio.h>

int main(void) {
    int a = 50000, b = 50000;
    long long safe = (long long)a * b;

    printf("int uses %zu bytes\n", sizeof(int));
    printf("long long uses %zu bytes\n", sizeof(long long));
    printf("50000 x 50000 = %lld\n", safe);
    return 0;
}', '', 'int uses 4 bytes
long long uses 8 bytes
50000 x 50000 = 2500000000', 'Casting a to long long before multiplying makes the whole multiplication happen in 64 bits, so the result 2,500,000,000 is correct.', 'গুণের আগে a কে long long-এ Cast করায় পুরো গুণটি ৬৪ বিটে হয়, তাই 2,500,000,000 সঠিকভাবে আসে।'
from public.lessons l join public.courses c on c.id = l.course_id where c.slug = 'c-programming' and l.slug = 'integer-and-long-integer';
