select l.id, 0, 'Division and precision', 'ভাগ ও Precision', 'c', '#include <stdio.h>

int main(void) {
    int total = 7, count = 2;
    printf("Integer division: %d\n", total / count);
    printf("Real division: %.2f\n", (double)total / count);
    printf("0.1 + 0.2 = %.17f\n", 0.1 + 0.2);
    return 0;
}', '', 'Integer division: 3
Real division: 3.50
0.1 + 0.2 = 0.30000000000000004', '7 / 2 between ints is 3. Casting total to double gives 3.50. Printing 17 decimals reveals that 0.1 + 0.2 is only approximately 0.3.', 'দুটি int এর মধ্যে 7 / 2 হয় 3। total কে double-এ Cast করলে 3.50 আসে। ১৭ ঘর দশমিক প্রিন্ট করলে দেখা যায় 0.1 + 0.2 আসলে প্রায় 0.3, হুবহু নয়।'
from public.lessons l join public.courses c on c.id = l.course_id where c.slug = 'c-programming' and l.slug = 'float-and-double';
