select l.id, 0, 'Pass or fail', 'পাস না ফেল', 'c', '#include <stdio.h>

int main(void) {
    int marks;
    scanf("%d", &marks);

    if (marks >= 33) {
        printf("Passed with %d marks\n", marks);
    } else {
        printf("Failed. Needed %d more marks\n", 33 - marks);
    }
    return 0;
}', '28', 'Failed. Needed 5 more marks', '28 >= 33 is false, so the else block runs and prints how many marks were missing.', '28 >= 33 মিথ্যা, তাই else ব্লক চলে এবং কত নম্বর কম ছিল তা প্রিন্ট করে।'
from public.lessons l join public.courses c on c.id = l.course_id where c.slug = 'c-programming' and l.slug = 'if-else';
