select l.id, 0, 'Grade ladder', 'গ্রেডের সিঁড়ি', 'c', '#include <stdio.h>

int main(void) {
    int marks;
    scanf("%d", &marks);

    if (marks < 0 || marks > 100) {
        printf("Invalid marks\n");
    } else if (marks >= 80) {
        printf("A+\n");
    } else if (marks >= 60) {
        printf("A-\n");
    } else if (marks >= 33) {
        printf("Pass\n");
    } else {
        printf("F\n");
    }
    return 0;
}', '72', 'A-', '72 is valid and not >= 80, but it is >= 60, so A- is printed and the remaining branches are skipped.', '72 বৈধ এবং >= 80 নয়, তবে >= 60, তাই A- প্রিন্ট হয় এবং বাকি শাখাগুলো আর যাচাই হয় না।'
