select l.id, 0, 'A small calculator', 'ছোট একটি ক্যালকুলেটর', 'c', '#include <stdio.h>

int main(void) {
    double a, b;
    char op;
    scanf("%lf %c %lf", &a, &op, &b);

    switch (op) {
        case ''+'': printf("%.2f\n", a + b); break;
        case ''-'': printf("%.2f\n", a - b); break;
        case ''*'': printf("%.2f\n", a * b); break;
        case ''/'':
            if (b == 0) printf("Cannot divide by zero\n");
            else printf("%.2f\n", a / b);
            break;
        default: printf("Unknown operator %c\n", op);
    }
    return 0;
}', '15 / 4', '3.75', 'op is ''/'', so that case runs. It checks for division by zero, prints 3.75 and then break leaves the switch.', 'op হলো ''/'', তাই সেই case চলে। শূন্য দিয়ে ভাগ হচ্ছে কিনা দেখে 3.75 প্রিন্ট করে, তারপর break দিয়ে switch থেকে বেরিয়ে যায়।'
from public.lessons l join public.courses c on c.id = l.course_id where c.slug = 'c-programming' and l.slug = 'switch-case';
