select l.id, 0, 'Precedence in action', 'Precedence-এর ব্যবহার', 'c', '#include <stdio.h>

int main(void) {
    int x = 5;
    printf("2 + 3 * 4 = %d\n", 2 + 3 * 4);
    printf("(2 + 3) * 4 = %d\n", (2 + 3) * 4);
    printf("20 / 4 / 5 = %d\n", 20 / 4 / 5);
    printf("17 %% 5 = %d\n", 17 % 5);
    printf("x++ gives %d, ", x++);
    printf("now x is %d\n", x);
    printf("5 > 3 && 2 > 4 is %d\n", 5 > 3 && 2 > 4);
    return 0;
}', '', '2 + 3 * 4 = 14
(2 + 3) * 4 = 20
20 / 4 / 5 = 1
17 % 5 = 2
x++ gives 5, now x is 6
5 > 3 && 2 > 4 is 0', 'Multiplication runs before addition; parentheses change that. Division is left-associative. %% prints a literal percent sign. x++ returns 5, then x becomes 6.', 'যোগের আগে গুণ হয়; Parentheses সেই ক্রম বদলে দেয়। ভাগ বাম থেকে ডানে হয়। %% দিয়ে শতাংশ চিহ্ন প্রিন্ট হয়। x++ প্রথমে 5 দেয়, তারপর x হয় 6।'
from public.lessons l join public.courses c on c.id = l.course_id where c.slug = 'c-programming' and l.slug = 'operators-precedence-associativity';
