select l.id, 0, 'Counting and summing', 'গণনা ও যোগফল', 'c', '#include <stdio.h>

int main(void) {
    int sum = 0;
    for (int i = 1; i <= 5; i++) {
        printf("%d ", i);
        sum += i;
    }
    printf("\nSum = %d\n", sum);
    return 0;
}', '', '1 2 3 4 5 
Sum = 15', 'i takes the values 1 to 5. Each value is printed and added to sum, which ends at 15.', 'i এর মান 1 থেকে 5 পর্যন্ত হয়। প্রতিটি মান প্রিন্ট হয় এবং sum-এ যোগ হয়, শেষে sum হয় 15।'
