select l.id, 0, 'Digit sum', 'অঙ্কের যোগফল', 'c', '#include <stdio.h>

int main(void) {
    int n, sum = 0;
    scanf("%d", &n);
    int original = n;

    while (n > 0) {
        sum += n % 10;
        n /= 10;
    }
    printf("Digit sum of %d is %d\n", original, sum);
    return 0;
}', '2024', 'Digit sum of 2024 is 8', 'n % 10 takes the last digit, n /= 10 removes it. The loop runs four times (4, 2, 0, 2) and the sum is 8. We kept a copy in original to print later.', 'n % 10 শেষ অঙ্কটি নেয়, n /= 10 সেটি সরিয়ে দেয়। লুপ চারবার চলে (4, 2, 0, 2), যোগফল 8। পরে প্রিন্ট করার জন্য আসল মানটি original-এ রেখে দিয়েছি।'
