select l.id, 0, 'Skip and stop', 'বাদ দেওয়া ও থামা', 'c', '#include <stdio.h>

int main(void) {
    for (int i = 1; i <= 20; i++) {
        if (i % 2 == 0) continue;   /* skip even numbers */
        if (i > 11) break;          /* stop after 11 */
        printf("%d ", i);
    }
    printf("\n");
    return 0;
}', '', '1 3 5 7 9 11', 'Even numbers are skipped with continue. When i reaches 13 (the first odd number above 11), break ends the loop.', 'জোড় সংখ্যাগুলো continue দিয়ে বাদ যায়। i যখন 13 হয় (11 এর পরের প্রথম বিজোড়), break লুপ শেষ করে দেয়।'
from public.lessons l join public.courses c on c.id = l.course_id where c.slug = 'c-programming' and l.slug = 'break-and-continue';
