select l.id, 0, 'Prime check with a flag', 'Flag দিয়ে মৌলিক সংখ্যা যাচাই', 'c', '#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);

    int isPrime = (n >= 2);
    for (int d = 2; (long long)d * d <= n; d++) {
        if (n % d == 0) {
            isPrime = 0;
            break;
        }
    }
    printf("%d is %s\n", n, isPrime ? "prime" : "not prime");
    return 0;
}', '97', '97 is prime', 'No divisor between 2 and 9 divides 97, so the flag stays 1. The condition (n >= 2) handles 0 and 1 correctly.', '2 থেকে 9 এর কোনোটি দিয়ে 97 বিভাজ্য নয়, তাই Flag 1-ই থাকে। (n >= 2) শর্তটি 0 আর 1 কে সঠিকভাবে সামলায়।'
from public.lessons l join public.courses c on c.id = l.course_id where c.slug = 'c-programming' and l.slug = 'loop-practice-problems';
