select l.id, 0, 'Read, sum and average', 'ইনপুট, যোগফল ও গড়', 'c', '#include <stdio.h>

int main(void) {
    int n, a[100];
    scanf("%d", &n);
    int sum = 0;
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
        sum += a[i];
    }
    printf("First: %d, Last: %d\n", a[0], a[n - 1]);
    printf("Average: %.2f\n", (double)sum / n);
    return 0;
}', '5
78 91 85 66 70', 'First: 78, Last: 70
Average: 78.00', 'The loop stores each value in a[i] and adds it to sum. The first element is a[0] and the last is a[n-1].', 'লুপ প্রতিটি মান a[i] তে রাখে এবং sum-এ যোগ করে। প্রথম উপাদান a[0], শেষটি a[n-1]।'
from public.lessons l join public.courses c on c.id = l.course_id where c.slug = 'c-programming' and l.slug = 'array-introduction';
