select l.id, 0, 'Max, search and reverse', 'সর্বোচ্চ, খোঁজা ও উল্টানো', 'c', '#include <stdio.h>

int main(void) {
    int a[] = {4, -2, 9, 7, 1};
    int n = 5, key = 7, pos = -1;

    int max = a[0];
    for (int i = 1; i < n; i++)
        if (a[i] > max) max = a[i];

    for (int i = 0; i < n; i++)
        if (a[i] == key) { pos = i; break; }

    for (int i = 0; i < n / 2; i++) {
        int t = a[i]; a[i] = a[n - 1 - i]; a[n - 1 - i] = t;
    }

    printf("Max: %d\n", max);
    printf("%d found at index %d\n", key, pos);
    printf("Reversed:");
    for (int i = 0; i < n; i++) printf(" %d", a[i]);
    printf("\n");
    return 0;
}', '', 'Max: 9
7 found at index 3
Reversed: 1 7 9 -2 4', 'Three separate loops: one finds the maximum (9), one finds 7 at index 3, and one swaps pairs from both ends to reverse the array.', 'তিনটি আলাদা লুপ: একটি সর্বোচ্চ মান (9) বের করে, একটি 7 কে Index 3 এ খুঁজে পায়, আরেকটি দুই প্রান্ত থেকে জোড়া swap করে Array উল্টে দেয়।'
from public.lessons l join public.courses c on c.id = l.course_id where c.slug = 'c-programming' and l.slug = 'array-operations';
