select l.id, 0, 'Matrix and its transpose', 'ম্যাট্রিক্স ও তার Transpose', 'c', '#include <stdio.h>

int main(void) {
    int m[2][3] = {{1, 2, 3}, {4, 5, 6}};

    printf("Matrix:\n");
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 3; j++) printf("%d ", m[i][j]);
        printf("\n");
    }

    printf("Transpose:\n");
    for (int j = 0; j < 3; j++) {
        for (int i = 0; i < 2; i++) printf("%d ", m[i][j]);
        printf("\n");
    }
    return 0;
}', '', 'Matrix:
1 2 3 
4 5 6 
Transpose:
1 4 
2 5 
3 6', 'The transpose swaps the roles of rows and columns, so the outer loop now runs over columns j and the inner loop over rows i.', 'Transpose-এ সারি আর কলামের ভূমিকা বদলে যায়, তাই এখন বাইরের লুপ চলে কলাম j এর ওপর আর ভেতরেরটি সারি i এর ওপর।'
