select l.id, 0, 'Prototype, definition and call', 'Prototype, Definition ও Call', 'c', '#include <stdio.h>

int square(int x);
void printLine(int n);

int main(void) {
    int a = 7;
    printLine(12);
    printf("%d squared is %d\n", a, square(a));
    printf("a is still %d\n", a);
    printLine(12);
    return 0;
}

int square(int x) {
    x = x * x;      /* changes only the local copy */
    return x;
}

void printLine(int n) {
    for (int i = 0; i < n; i++) printf("-");
    printf("\n");
}', '', '------------
7 squared is 49
a is still 7
------------', 'square changes its own copy x, so a stays 7 in main. printLine is void: it does its job and returns nothing.', 'square নিজের কপি x বদলায়, তাই main-এ a থাকে 7-ই। printLine void — কাজ করে কিন্তু কিছু Return করে না।'
from public.lessons l join public.courses c on c.id = l.course_id where c.slug = 'c-programming' and l.slug = 'function-introduction';
