select l.id, 0, 'Arrays and recursion', 'Array ও Recursion', 'c', '#include <stdio.h>

int sumArray(int a[], int n) {
    int s = 0;
    for (int i = 0; i < n; i++) s += a[i];
    return s;
}

int gcd(int a, int b) {
    if (b == 0) return a;        /* base case */
    return gcd(b, a % b);        /* recursive case */
}

long long factorial(int n) {
    return n <= 1 ? 1 : n * factorial(n - 1);
}

int main(void) {
    int marks[] = {10, 20, 30, 40};
    printf("Sum: %d\n", sumArray(marks, 4));
    printf("gcd(84, 36) = %d\n", gcd(84, 36));
    printf("10! = %lld\n", factorial(10));
    return 0;
}', '', 'Sum: 100
gcd(84, 36) = 12
10! = 3628800', 'sumArray receives the array and its length. gcd and factorial are recursive: each call works on a smaller problem until the base case returns directly.', 'sumArray Array আর তার দৈর্ঘ্য গ্রহণ করে। gcd আর factorial Recursive: প্রতিটি কল ছোট সমস্যা নিয়ে কাজ করে যতক্ষণ না Base Case সরাসরি Return করে।'
from public.lessons l join public.courses c on c.id = l.course_id where c.slug = 'c-programming' and l.slug = 'function-exercises';
