select l.id, 0, 'Students in a struct array', 'struct Array-তে শিক্ষার্থী', 'c', '#include <stdio.h>

typedef struct {
    char name[30];
    int roll;
    double cgpa;
} Student;

int main(void) {
    Student list[3] = {
        {"Araf", 1, 3.45},
        {"Mim", 2, 3.92},
        {"Tanvir", 3, 3.60}
    };

    int best = 0;
    for (int i = 1; i < 3; i++)
        if (list[i].cgpa > list[best].cgpa) best = i;

    for (int i = 0; i < 3; i++)
        printf("%-8s roll %d  CGPA %.2f\n", list[i].name, list[i].roll, list[i].cgpa);
    printf("Top: %s\n", list[best].name);
    return 0;
}', '', 'Araf     roll 1  CGPA 3.45
Mim      roll 2  CGPA 3.92
Tanvir   roll 3  CGPA 3.60
Top: Mim', 'Each element of list is a whole Student. We compare cgpa members to find the best one; %-8s left-aligns names in an 8-character column.', 'list এর প্রতিটি উপাদান একটি পূর্ণ Student। cgpa Member তুলনা করে সেরাজন বের করা হয়; %-8s নামগুলোকে ৮ ঘরের কলামে বামে সাজায়।'
