select l.id, 0, 'Address, value and swap', 'Address, মান ও swap', 'c', '#include <stdio.h>

void swap(int *a, int *b) {
    int t = *a;
    *a = *b;
    *b = t;
}

int main(void) {
    int x = 10, y = 20;
    int *p = &x;

    *p = 25;
    printf("x = %d (changed through p)\n", x);
    printf("p points to x? %s\n", p == &x ? "yes" : "no");

    swap(&x, &y);
    printf("After swap: x = %d, y = %d\n", x, y);
    return 0;
}', '', 'x = 25 (changed through p)
p points to x? yes
After swap: x = 20, y = 25', 'Writing *p = 25 changes x itself. swap receives the addresses of x and y, so its changes are visible in main.', '*p = 25 লিখলে x নিজেই বদলে যায়। swap x আর y এর Address পায়, তাই তার করা পরিবর্তন main-এও দেখা যায়।'
