select l.id, 0, 'malloc, calloc, realloc and free', 'malloc, calloc, realloc ও free', 'c', '#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n = 3;
    int *a = malloc(n * sizeof(int));
    int *zeros = calloc(4, sizeof(int));
    if (a == NULL || zeros == NULL) return 1;

    for (int i = 0; i < n; i++) a[i] = (i + 1) * 10;

    int *bigger = realloc(a, 5 * sizeof(int));
    if (bigger == NULL) { free(a); free(zeros); return 1; }
    a = bigger;
    a[3] = 40; a[4] = 50;

    printf("a:");
    for (int i = 0; i < 5; i++) printf(" %d", a[i]);
    printf("\nzeros:");
    for (int i = 0; i < 4; i++) printf(" %d", zeros[i]);
    printf("\n");

    free(a);
    free(zeros);
    return 0;
}', '', 'a: 10 20 30 40 50
zeros: 0 0 0 0', 'malloc gives room for 3 ints, realloc grows it to 5 while keeping 10, 20, 30. calloc''s memory starts as zeros. Both blocks are freed at the end.', 'malloc ৩টি int এর জায়গা দেয়, realloc সেটিকে ৫টিতে বাড়ায় এবং 10, 20, 30 ঠিক রাখে। calloc এর মেমোরি শুরুতেই শূন্য। শেষে দুটো ব্লকই free করা হয়।'
from public.lessons l join public.courses c on c.id = l.course_id where c.slug = 'c-programming' and l.slug = 'dynamic-memory-allocation';
