select l.id, 0, 'Arrays, pointers and ->', 'Array, Pointer ও ->', 'c', '#include <stdio.h>

typedef struct { char name[20]; int marks; } Student;

void addBonus(int *a, int n, int bonus) {
    for (int *p = a; p < a + n; p++) *p += bonus;
}

void promote(Student *s) {
    s->marks += 5;
}

int main(void) {
    int a[] = {60, 72, 85};
    printf("a[1] = %d, *(a + 1) = %d\n", a[1], *(a + 1));

    addBonus(a, 3, 3);
    printf("After bonus: %d %d %d\n", a[0], a[1], a[2]);

    Student s = {"Riya", 78};
    promote(&s);
    printf("%s now has %d\n", s.name, s.marks);
    return 0;
}', '', 'a[1] = 72, *(a + 1) = 72
After bonus: 63 75 88
Riya now has 83', 'a[1] and *(a + 1) are the same element. addBonus walks the array with a pointer and changes the caller''s data. promote updates the struct through s->marks.', 'a[1] আর *(a + 1) একই উপাদান। addBonus একটি Pointer দিয়ে Array-তে হাঁটে এবং কলারের ডেটা বদলায়। promote s->marks দিয়ে Structure আপডেট করে।'
from public.lessons l join public.courses c on c.id = l.course_id where c.slug = 'c-programming' and l.slug = 'pointer-array-function';
