select l.id, 0, 'Write, then read back', 'লেখা, তারপর আবার পড়া', 'c', '#include <stdio.h>

int main(void) {
    FILE *fp = fopen("marks.txt", "w");
    if (fp == NULL) { printf("Cannot open file\n"); return 1; }
    fputs("Marks of section A\n", fp);
    fprintf(fp, "%d %d %d\n", 78, 91, 85);
    fclose(fp);

    fp = fopen("marks.txt", "r");
    if (fp == NULL) return 1;
    char title[50];
    fgets(title, sizeof title, fp);
    printf("Title: %s", title);

    int x, sum = 0;
    while (fscanf(fp, "%d", &x) == 1) sum += x;
    fclose(fp);

    printf("Sum of marks: %d\n", sum);
    return 0;
}', '', 'Title: Marks of section A
Sum of marks: 254', 'The program writes a title line and three numbers, closes the file, reopens it for reading, reads the title with fgets and the numbers with fscanf until no more integers can be read.', 'প্রোগ্রামটি একটি শিরোনাম লাইন আর তিনটি সংখ্যা লেখে, ফাইল বন্ধ করে, আবার পড়ার জন্য খোলে, fgets দিয়ে শিরোনাম আর fscanf দিয়ে সংখ্যাগুলো পড়ে যতক্ষণ না আর কোনো Integer পাওয়া যায়।'
from public.lessons l join public.courses c on c.id = l.course_id where c.slug = 'c-programming' and l.slug = 'file-handling';
