select l.id, 0, 'Record keeper core', 'রেকর্ড-কিপারের মূল অংশ', 'c', '#include <stdio.h>

typedef struct { int roll; char name[30]; double cgpa; } Student;

void addStudent(const char *path, Student s) {
    FILE *fp = fopen(path, "a");
    if (!fp) return;
    fprintf(fp, "%d %s %.2f\n", s.roll, s.name, s.cgpa);
    fclose(fp);
}

int findByRoll(const char *path, int roll, Student *out) {
    FILE *fp = fopen(path, "r");
    if (!fp) return 0;
    Student s;
    while (fscanf(fp, "%d %29s %lf", &s.roll, s.name, &s.cgpa) == 3) {
        if (s.roll == roll) { *out = s; fclose(fp); return 1; }
    }
    fclose(fp);
    return 0;
}

int main(void) {
    const char *path = "students.txt";
    remove(path);
    addStudent(path, (Student){1, "Araf", 3.45});
    addStudent(path, (Student){2, "Mim", 3.92});
    addStudent(path, (Student){3, "Tanvir", 3.60});

    Student found;
    if (findByRoll(path, 2, &found))
        printf("Roll 2: %s, CGPA %.2f\n", found.name, found.cgpa);
    if (!findByRoll(path, 9, &found))
        printf("Roll 9 not found\n");
    return 0;
}', '', 'Roll 2: Mim, CGPA 3.92
Roll 9 not found', 'addStudent appends one line per record. findByRoll scans the file until the roll matches and returns the record through a pointer. remove() starts each run with a fresh file.', 'addStudent প্রতিটি রেকর্ডের জন্য একটি লাইন যোগ করে। findByRoll রোল না মেলা পর্যন্ত ফাইল পড়ে এবং Pointer দিয়ে রেকর্ডটি ফেরত দেয়। remove() প্রতিবার নতুন ফাইল দিয়ে শুরু করায়।'
