select l.id, 0, 'Stopwatch core with simulated laps', 'Simulated ল্যাপসহ স্টপওয়াচের মূল অংশ', 'c', '#include <stdio.h>

void formatTime(int t, char *out) {
    int h = t / 3600;
    int m = (t % 3600) / 60;
    int s = t % 60;
    sprintf(out, "%02d:%02d:%02d", h, m, s);
}

int main(void) {
    int laps[] = {65, 125, 3661};   /* seconds when lap was pressed */
    int lapCount = 3;
    char buf[16];

    for (int i = 0; i < lapCount; i++) {
        formatTime(laps[i], buf);
        int split = laps[i] - (i ? laps[i - 1] : 0);
        char splitBuf[16];
        formatTime(split, splitBuf);
        printf("Lap %d  %s  (+%s)\n", i + 1, buf, splitBuf);
    }
    return 0;
}', '', 'Lap 1  00:01:05  (+00:01:05)
Lap 2  00:02:05  (+00:01:00)
Lap 3  01:01:01  (+00:58:56)', 'formatTime converts seconds to HH:MM:SS with zero padding using sprintf. Each lap also shows the split — the time since the previous lap.', 'formatTime sprintf দিয়ে সেকেন্ডকে শূন্য-প্যাডসহ HH:MM:SS এ রূপান্তর করে। প্রতিটি ল্যাপে Split-ও দেখায় — আগের ল্যাপ থেকে কত সময় গেছে।'
