select c.id, ch.id, 'while-loops-python', 6, 'while Loops', 'while Loop', 'Repeat until a condition changes.', 'শর্ত না বদলানো পর্যন্ত বারবার চালানো।',
  array['Write while loops', 'Process digits of a number', 'Avoid infinite loops']::text[], array['while Loop লেখা', 'সংখ্যার অঙ্ক নিয়ে কাজ', 'Infinite Loop এড়ানো']::text[], '`while` repeats while its condition is true — use it when the number of steps isn''t known in advance.

```python
n = 12045
